-- TransitTechOS product + analytics data for Databricks, exported from transit_orchestrator (Postgres) 2026-10-13 10:54
-- CREATE OR REPLACE TABLE: safe to re-run; each run replaces these tables with this snapshot.
-- Not included: audit_records (already streamed to Databricks by the app) and app-internal tables.

CREATE SCHEMA IF NOT EXISTS workspace.transit_orchestrator;

-- ############ Shared identity ############

-- ===== tenants: agencies (MVT, LSP); every row is scoped by tenant_id =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tenants (
  `id` STRING NOT NULL,
  `code` STRING NOT NULL,
  `name` STRING NOT NULL,
  `timezone` STRING NOT NULL,
  `agent_persona` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'agencies (MVT, LSP); every row is scoped by tenant_id. Primary key: id';

-- ===== canonical_entities: immutable shared IDs for vehicles, drivers and trips =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.canonical_entities (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `entity_type` STRING NOT NULL,
  `label` STRING NOT NULL
) USING DELTA COMMENT 'immutable shared IDs for vehicles, drivers and trips. Primary key: id';

-- ===== identity_crosswalk: interim crosswalk: shared ID -> each product's own ID =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.identity_crosswalk (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `entity_type` STRING NOT NULL,
  `canonical_id` STRING NOT NULL,
  `system` STRING NOT NULL,
  `external_id` STRING NOT NULL
) USING DELTA COMMENT 'interim crosswalk: shared ID -> each product\'s own ID. Primary key: id';

-- ############ 1. Vehicle health and telematics (Telematics, Asset Mgmt) ############

-- ===== tl_devices: telematics device per vehicle =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tl_devices (
  `device_id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `firmware` STRING NOT NULL,
  `online` BOOLEAN NOT NULL
) USING DELTA COMMENT 'telematics device per vehicle. Primary key: device_id';

-- ===== tl_readings: telemetry readings: engine temp, oil pressure, battery, speed, fault codes =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tl_readings (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `device_id` STRING NOT NULL,
  `ts` TIMESTAMP NOT NULL,
  `engine_temp_c` DOUBLE NOT NULL,
  `oil_pressure_kpa` DOUBLE NOT NULL,
  `battery_v` DOUBLE NOT NULL,
  `speed_kph` DOUBLE NOT NULL,
  `odometer` INT NOT NULL,
  `dtc_codes` STRING NOT NULL
) USING DELTA COMMENT 'telemetry readings: engine temp, oil pressure, battery, speed, fault codes. Primary key: id';

-- ===== am_fault_codes: diagnostic trouble code catalog with severity and repair hours =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_fault_codes (
  `code` STRING NOT NULL,
  `description` STRING NOT NULL,
  `system` STRING NOT NULL,
  `severity` STRING NOT NULL,
  `est_repair_hours` INT NOT NULL,
  `affects_accessibility` BOOLEAN NOT NULL
) USING DELTA COMMENT 'diagnostic trouble code catalog with severity and repair hours. Primary key: code';

-- ===== events: business events from the products: faults, PM overdue, no-shows (CloudEvents) =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.events (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `type` STRING NOT NULL,
  `source` STRING NOT NULL,
  `subject` STRING,
  `time` TIMESTAMP NOT NULL,
  `data` STRING NOT NULL,
  `dedupe_key` STRING,
  `status` STRING NOT NULL,
  `error` STRING,
  `note` STRING,
  `correlation_id` STRING,
  `trace_id` STRING,
  `received_at` TIMESTAMP NOT NULL,
  `processed_at` TIMESTAMP
) USING DELTA COMMENT 'business events from the products: faults, PM overdue, no-shows (CloudEvents). Primary key: id';

-- ############ 2. Asset and maintenance status (FASTER) ############

-- ===== am_assets: vehicles as assets: make, model, VIN, odometer, PM interval, status =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_assets (
  `asset_number` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `unit_label` STRING NOT NULL,
  `make` STRING NOT NULL,
  `model` STRING NOT NULL,
  `year` INT NOT NULL,
  `vin` STRING NOT NULL,
  `odometer` INT NOT NULL,
  `last_pm_date` DATE NOT NULL,
  `last_pm_odometer` INT NOT NULL,
  `pm_interval_miles` INT NOT NULL,
  `status` STRING NOT NULL,
  `depot` STRING NOT NULL
) USING DELTA COMMENT 'vehicles as assets: make, model, VIN, odometer, PM interval, status. Primary key: asset_number';

-- ===== am_work_orders: maintenance work orders with shop window =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_work_orders (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `asset_number` STRING NOT NULL,
  `status` STRING NOT NULL,
  `priority` STRING NOT NULL,
  `fault_code` STRING,
  `title` STRING NOT NULL,
  `description` STRING NOT NULL,
  `source` STRING NOT NULL,
  `shop_depot` STRING,
  `shop_start` TIMESTAMP,
  `shop_end` TIMESTAMP,
  `external_ref` STRING,
  `created_by` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `closed_at` TIMESTAMP,
  `closed_by` STRING,
  `resolution` STRING
) USING DELTA COMMENT 'maintenance work orders with shop window. Primary key: id';

-- ===== am_shop_capacity: shop bays per depot per day (maintenance windows) =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.am_shop_capacity (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `depot` STRING NOT NULL,
  `day` DATE NOT NULL,
  `bays_total` INT NOT NULL,
  `bays_booked` INT NOT NULL
) USING DELTA COMMENT 'shop bays per depot per day (maintenance windows). Primary key: id';

-- ===== tm_availability_blocks: vehicle marked unavailable / returned to service =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_availability_blocks (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `vehicle_code` STRING NOT NULL,
  `start` TIMESTAMP NOT NULL,
  `end` TIMESTAMP NOT NULL,
  `reason` STRING NOT NULL,
  `source_ref` STRING,
  `active` BOOLEAN NOT NULL,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'vehicle marked unavailable / returned to service. Primary key: id';

-- ############ 3. Trip and schedule data (Ecolane / TripMaster) ############

-- ===== tm_vehicles: schedulable vehicles: type, capacity, wheelchair positions, depot =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_vehicles (
  `vehicle_code` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `label` STRING NOT NULL,
  `vehicle_type` STRING NOT NULL,
  `capacity` INT NOT NULL,
  `wheelchair_positions` INT NOT NULL,
  `depot` STRING NOT NULL,
  `status` STRING NOT NULL
) USING DELTA COMMENT 'schedulable vehicles: type, capacity, wheelchair positions, depot. Primary key: vehicle_code';

-- ===== tm_drivers: drivers known to trip management =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_drivers (
  `driver_code` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `name` STRING NOT NULL
) USING DELTA COMMENT 'drivers known to trip management. Primary key: driver_code';

-- ===== tm_runs: runs: vehicle + driver + shift, by service date =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_runs (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `service_date` DATE NOT NULL,
  `route_name` STRING NOT NULL,
  `block_name` STRING NOT NULL,
  `start_time` TIMESTAMP NOT NULL,
  `end_time` TIMESTAMP NOT NULL,
  `vehicle_code` STRING,
  `driver_code` STRING,
  `status` STRING NOT NULL,
  `original_vehicle_code` STRING,
  `original_driver_code` STRING,
  `reassigned` BOOLEAN NOT NULL,
  `reassignment_ref` STRING,
  `delay_minutes` INT NOT NULL
) USING DELTA COMMENT 'runs: vehicle + driver + shift, by service date. Primary key: id';

-- ===== tm_trips: trips: rider pickups/drop-offs with time windows =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_trips (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `run_id` STRING NOT NULL,
  `rider_id` STRING NOT NULL,
  `pickup_time` TIMESTAMP NOT NULL,
  `eta` TIMESTAMP NOT NULL,
  `pickup_stop` STRING NOT NULL,
  `dropoff_stop` STRING NOT NULL,
  `needs_wheelchair` BOOLEAN NOT NULL,
  `status` STRING NOT NULL,
  `source_ref` STRING
) USING DELTA COMMENT 'trips: rider pickups/drop-offs with time windows. Primary key: id';

-- ===== tm_trip_requests: trip requests and cancellations =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_trip_requests (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `rider_id` STRING NOT NULL,
  `service_date` DATE NOT NULL,
  `route_name` STRING NOT NULL,
  `window_start` TIMESTAMP NOT NULL,
  `window_end` TIMESTAMP NOT NULL,
  `pickup_stop` STRING NOT NULL,
  `dropoff_stop` STRING NOT NULL,
  `purpose` STRING NOT NULL,
  `needs_wheelchair` BOOLEAN NOT NULL,
  `status` STRING NOT NULL,
  `booked_trip_id` STRING,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'trip requests and cancellations. Primary key: id';

-- ===== tm_no_show_log: passenger no-shows and late cancellations =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.tm_no_show_log (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `rider_id` STRING NOT NULL,
  `trip_id` STRING,
  `service_date` DATE NOT NULL,
  `kind` STRING NOT NULL
) USING DELTA COMMENT 'passenger no-shows and late cancellations. Primary key: id';

-- ############ 4. Driver and workforce information (Bytecurve) ############

-- ===== wf_employees: drivers: license class, certifications, depot, max daily hours =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.wf_employees (
  `employee_number` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `full_name` STRING NOT NULL,
  `license_class` STRING NOT NULL,
  `certifications` STRING NOT NULL,
  `status` STRING NOT NULL,
  `home_depot` STRING NOT NULL,
  `max_daily_hours` DOUBLE NOT NULL,
  `phone` STRING NOT NULL,
  `hire_date` DATE
) USING DELTA COMMENT 'drivers: license class, certifications, depot, max daily hours. Primary key: employee_number';

-- ############ 5. Safety and compliance records (Vestige) ############

-- ===== sf_drivers: driver compliance: medical card, drug test, securement training, incidents =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.sf_drivers (
  `safety_id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `name` STRING NOT NULL,
  `medical_card_expires` DATE NOT NULL,
  `drug_test_due` DATE NOT NULL,
  `securement_training_due` DATE NOT NULL,
  `status` STRING NOT NULL,
  `preventable_incidents_12m` INT NOT NULL,
  `notes` STRING NOT NULL
) USING DELTA COMMENT 'driver compliance: medical card, drug test, securement training, incidents. Primary key: safety_id';

-- ===== sf_defects: vehicle safety defects and out-of-service flags =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.sf_defects (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `vehicle_ref` STRING NOT NULL,
  `category` STRING NOT NULL,
  `severity` STRING NOT NULL,
  `description` STRING NOT NULL,
  `status` STRING NOT NULL,
  `out_of_service` BOOLEAN NOT NULL,
  `source` STRING NOT NULL,
  `external_ref` STRING,
  `work_order_id` STRING,
  `created_by` STRING NOT NULL,
  `created_at` TIMESTAMP NOT NULL,
  `closed_at` TIMESTAMP,
  `closed_by` STRING,
  `resolution` STRING
) USING DELTA COMMENT 'vehicle safety defects and out-of-service flags. Primary key: id';

-- ############ 6. Rider communications (TripShot / Passio) ############

-- ===== rc_riders: riders and contact preferences =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.rc_riders (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `name` STRING NOT NULL,
  `phone` STRING NOT NULL,
  `email` STRING NOT NULL,
  `preferred_channel` STRING NOT NULL,
  `language` STRING NOT NULL
) USING DELTA COMMENT 'riders and contact preferences. Primary key: id';

-- ===== rc_notifications: notifications / ETA updates sent to riders =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.rc_notifications (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `rider_id` STRING NOT NULL,
  `trip_id` STRING,
  `channel` STRING NOT NULL,
  `kind` STRING NOT NULL,
  `message` STRING NOT NULL,
  `status` STRING NOT NULL,
  `workflow_id` STRING,
  `idempotency_key` STRING,
  `created_at` TIMESTAMP NOT NULL
) USING DELTA COMMENT 'notifications / ETA updates sent to riders. Primary key: id';

-- ############ 7. Operational history and analytics (Databricks pipelines) ############

-- ===== an_run_history: historical run outcomes: on-time performance per operator and day =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.an_run_history (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `service_date` DATE NOT NULL,
  `dow` INT NOT NULL,
  `route_name` STRING NOT NULL,
  `block` STRING NOT NULL,
  `hour_band` STRING NOT NULL,
  `depot` STRING NOT NULL,
  `vehicle_label` STRING NOT NULL,
  `vehicle_type` STRING NOT NULL,
  `driver_id` STRING NOT NULL,
  `driver_name` STRING NOT NULL,
  `driver_tenure_years` DOUBLE NOT NULL,
  `weather` STRING NOT NULL,
  `scheduled_trips` INT NOT NULL,
  `completed_trips` INT NOT NULL,
  `no_shows` INT NOT NULL,
  `late_cancels` INT NOT NULL,
  `wheelchair_boardings` INT NOT NULL,
  `load_factor` DOUBLE NOT NULL,
  `recovery_min` DOUBLE NOT NULL,
  `avg_dwell_min` DOUBLE NOT NULL,
  `pm_overdue` BOOLEAN NOT NULL,
  `road_call` BOOLEAN NOT NULL,
  `on_time_pickups` INT NOT NULL,
  `late_pickups` INT NOT NULL,
  `avg_late_min` DOUBLE NOT NULL
) USING DELTA COMMENT 'historical run outcomes: on-time performance per operator and day. Primary key: id';

-- ===== an_models: Operator Performance model versions and metrics =====
CREATE OR REPLACE TABLE workspace.transit_orchestrator.an_models (
  `id` STRING NOT NULL,
  `tenant_id` STRING NOT NULL,
  `version` INT NOT NULL,
  `kind` STRING NOT NULL,
  `trained_at` TIMESTAMP NOT NULL,
  `trained_by` STRING NOT NULL,
  `rows` INT NOT NULL,
  `date_from` DATE NOT NULL,
  `date_to` DATE NOT NULL,
  `metrics` STRING NOT NULL,
  `params` STRING NOT NULL,
  `active` BOOLEAN NOT NULL,
  `notes` STRING
) USING DELTA COMMENT 'Operator Performance model versions and metrics. Primary key: id';

